const feedback=document.querySelector('#copy-feedback');const timers=new WeakMap();const labels=new WeakMap();
async function copy(text,button){if(!labels.has(button))labels.set(button,button.innerHTML);const old=labels.get(button);clearTimeout(timers.get(button));try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);button.textContent='Copied!';if(feedback)feedback.textContent=text.includes('\n')?'Selected code list copied.':text+' copied.';timers.set(button,setTimeout(()=>button.innerHTML=old,2200));}catch{if(feedback)feedback.textContent='Copy was blocked. Select the full code and copy it manually.';}}
document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>copy(b.dataset.copy,b)));
document.querySelector('[data-copy-all]')?.addEventListener('click',event=>copy([...document.querySelectorAll('[data-copy]')].map(b=>b.dataset.copy).join('\n'),event.currentTarget));
const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open);});
document.querySelectorAll('[data-role-filter]').forEach(button=>button.addEventListener('click',()=>{const role=button.dataset.roleFilter;document.querySelectorAll('[data-role-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let total=0;document.querySelectorAll('[data-ability-role]').forEach(tile=>{tile.hidden=role!=='All'&&tile.dataset.abilityRole!==role;if(!tile.hidden)total++;});document.querySelectorAll('[data-tier-row]').forEach(row=>row.hidden=![...row.querySelectorAll('[data-ability-role]')].some(t=>!t.hidden));document.querySelector('#ability-count').textContent=total+' abilities';}));
const rewards=document.querySelector('#reward-data');if(rewards){const data=JSON.parse(rewards.textContent),balance=document.querySelector('#gem-balance'),goal=document.querySelector('#gem-goal'),custom=document.querySelector('#custom-goal');function update(){const sums={gems:0,spins:0,gemBoost:0,coinBoost:0,emotes:0,titles:0};document.querySelectorAll('[data-code-choice]').forEach(input=>{if(input.checked)for(const k of Object.keys(sums))sums[k]+=data[Number(input.dataset.codeChoice)][k]||0;});const valid=n=>Number.isFinite(n)&&n>=0&&Number.isInteger(n)&&n<=100000000;const current=Number(balance.value),target=Number(goal.value==='custom'?custom.value:goal.value),invalid=!valid(current)||!valid(target)||balance.value===''||(goal.value==='custom'&&custom.value==='');document.querySelector('#custom-goal-field').hidden=goal.value!=='custom';for(const [id,key]of [['total-gems','gems'],['total-spins','spins'],['total-gem-boost','gemBoost'],['total-coin-boost','coinBoost']])document.getElementById(id).textContent=sums[key].toLocaleString('en-US');document.querySelector('#total-cosmetics').textContent=[sums.emotes?`${sums.emotes} random emote${sums.emotes===1?'':'s'}`:'',sums.titles?`${sums.titles} title${sums.titles===1?'':'s'}`:''].filter(Boolean).join(' + ')||'None selected';document.querySelector('#remaining-gems').textContent=invalid?'—':Math.max(0,target-current-sums.gems).toLocaleString('en-US');document.querySelector('#calc-feedback').textContent=invalid?'Enter whole, non-negative Gem amounts up to 100,000,000.':'';}document.querySelectorAll('[data-code-choice],#gem-balance,#gem-goal,#custom-goal').forEach(el=>el.addEventListener('input',update));update();}
